function i(e){if(!e)return"—";const r=new Date(String(e).replace(" ","T"));if(Number.isNaN(r.getTime()))return String(e);const t=n=>String(n).padStart(2,"0");return`${r.getFullYear()}-${t(r.getMonth()+1)}-${t(r.getDate())} ${t(r.getHours())}:${t(r.getMinutes())}`}function a(e){return!e&&e!==0?"—":e<1024?`${e} B`:e<1024*1024?`${Math.round(e/1024)} KB`:`${(e/1048576).toFixed(1)} MB`}function u(e,r){if(!e||!r)return null;const t=new Date(String(e).replace(" ","T")).getTime(),n=new Date(String(r).replace(" ","T")).getTime();return Number.isNaN(t)||Number.isNaN(n)?null:(n-t)/1e3}function f(e=""){return String(e).replace(/[\\/:*?"<>|]/g," ").trim()||"bilingual-book"}export{a,f as b,u as d,i as f};
